#### Example 1: Props-Based State Communication

_[To be completed]_

```typescript
// Extension props interface with state and callbacks
export interface ClaimsValidatorProps {
  // Input state from host
  claimId: string;
  claimData: ClaimData;
  tenantConfig: TenantConfig;

  // Callbacks for extension-to-host communication
  onValidationComplete: (result: ValidationResult) => void;
  onErrorOccurred: (error: Error) => void;

  // Context information
  context: ExtensionContext;
}

// Extension implementation
export const ClaimsValidator: React.FC<ClaimsValidatorProps> = React.memo(({
  claimId,
  claimData,
  onValidationComplete,
  onErrorOccurred
}) => {
  const handleValidate = async () => {
    try {
      const result = await validateClaim(claimData);
      onValidationComplete(result);
    } catch (error) {
      onErrorOccurred(error);
    }
  };

  return <ValidationUI onValidate={handleValidate} />;
});
```

