#### Example 2: Event Bus Communication

_[To be completed]_

```typescript
// Event bus for loosely coupled communication
import { EventBus } from '@gainwell/extensions-sdk-react';

// Extension publishes event
export const ClaimsValidator = () => {
  const eventBus = useEventBus();

  const handleValidationComplete = (result: ValidationResult) => {
    eventBus.publish('claims:validation:complete', {
      claimId: result.claimId,
      isValid: result.isValid,
      errors: result.errors
    });
  };

  return <ValidationUI onComplete={handleValidationComplete} />;
};

// Host application or other extension subscribes to event
export const ClaimsSummary = () => {
  const eventBus = useEventBus();
  const [validationStatus, setValidationStatus] = useState(null);

  useEffect(() => {
    const unsubscribe = eventBus.subscribe(
      'claims:validation:complete',
      (payload) => {
        setValidationStatus(payload);
      }
    );

    return unsubscribe;
  }, [eventBus]);

  return <SummaryDisplay status={validationStatus} />;
};
```

