#### Example 3: Redux Store Integration

_[To be completed]_

```typescript
// Extension accessing shared Redux store
import { useSelector, useDispatch } from 'react-redux';
import { updateClaimValidation } from '@gainwell/shared-store/claims';

export const ClaimsValidator = () => {
  // Access host application state
  const claim = useSelector((state) => state.claims.currentClaim);
  const dispatch = useDispatch();

  const handleValidate = async () => {
    const result = await validateClaim(claim);

    // Update shared state
    dispatch(updateClaimValidation({
      claimId: claim.id,
      validationResult: result
    }));
  };

  return <ValidationUI claim={claim} onValidate={handleValidate} />;
};
```

