#### Example 4: Context API for Extension State

_[To be completed]_

```typescript
// Extension-specific context for internal state
import React, { createContext, useContext, useState } from 'react';

interface ExtensionState {
  validationProgress: number;
  errors: ValidationError[];
  isValidating: boolean;
}

const ExtensionContext = createContext<ExtensionState | null>(null);

export const ExtensionProvider: React.FC = ({ children }) => {
  const [state, setState] = useState<ExtensionState>({
    validationProgress: 0,
    errors: [],
    isValidating: false
  });

  return (
    <ExtensionContext.Provider value={state}>
      {children}
    </ExtensionContext.Provider>
  );
};

export const useExtensionState = () => {
  const context = useContext(ExtensionContext);
  if (!context) {
    throw new Error('useExtensionState must be used within ExtensionProvider');
  }
  return context;
};
```

