#### Example 5: Data Fetching with React Query

_[To be completed]_

```typescript
// Extension using React Query for data fetching
import { useQuery, useMutation } from '@tanstack/react-query';
import { useQueryClient } from '@gainwell/extensions-sdk-react';

export const ClaimsValidator = ({ claimId }) => {
  const queryClient = useQueryClient();

  // Fetch validation rules
  const { data: rules, isLoading } = useQuery({
    queryKey: ['validationRules', claimId],
    queryFn: () => fetchValidationRules(claimId),
    // Share cache with host application
    staleTime: 5 * 60 * 1000 // 5 minutes
  });

  // Mutation for validation
  const validation = useMutation({
    mutationFn: (data) => validateClaim(data),
    onSuccess: (result) => {
      // Invalidate related queries in host app
      queryClient.invalidateQueries({ queryKey: ['claims', claimId] });
    }
  });

  return <ValidationUI rules={rules} onValidate={validation.mutate} />;
};
```
